    if n.get("type") == "text":
        return n.get("text", "")
    return "".join(text_of(k) for k in n.get("content", []) or [])


def src_of(n):
    for k in n.get("content", []) or []:
        if k.get("type") == "image2":
            return k["attrs"].get("src", "")
    return (n.get("attrs") or {}).get("url", "") or (n.get("attrs") or {}).get("videoId", "")


def fingerprint(n):
    return src_of(n) + " " + text_of(n)


